package com.siam.deviceinfo.adapter; import android.view.*;import android.widget.*;import android.content.*;import android.net.wifi.*;import java.util.*;import com.siam.deviceinfo.R;
public class WifiAdapter extends BaseAdapter {Context c;List<ScanResult> a;public WifiAdapter(Context c,List<ScanResult>a){this.c=c;this.a=a;}public int getCount(){return a.size();}public Object getItem(int i){return a.get(i);}public long getItemId(int i){return i;}public View getView(int i,View v,android.view.ViewGroup g){if(v==null)v=LayoutInflater.from(c).inflate(R.layout.item_wifi,g,false);ScanResult x=a.get(i);((TextView)v.findViewById(R.id.wifi_ssid)).setText(x.SSID.isEmpty()?"লুকানো নেটওয়ার্ক":x.SSID);((TextView)v.findViewById(R.id.wifi_signal)).setText(x.level+" dBm");return v;}}
